/* eslint-disable react/prop-types */
import React, { useEffect, useState, useMemo } from 'react';
import { Helmet } from 'react-helmet-async';
import { useLocation } from 'react-router-dom';
import InputLabel from '@mui/material/InputLabel';
import FormControl from '@mui/material/FormControl';
import Select from '@mui/material/Select';
import {
  Card,
  Table,
  Stack,
  Paper,
  Button,
  TableRow,
  MenuItem,
  TableBody,
  TableCell,
  Typography,
  IconButton,
  TableContainer,
  TablePagination,
  Menu,
  Modal,
  Box,
  Switch,
  Popover,
} from '@mui/material';
import TextField from '@mui/material/TextField';
import MoreVertIcon from '@mui/icons-material/MoreVert';
import { axios } from '../../utils/axios';
import { updateUrlParams } from '../../utils/urlUtilis';
// components
import Iconify from '../../components/iconify';
import Scrollbar from '../../components/scrollbar';
// sections
import { UserListHead, UserListToolbar } from '../../sections/@dashboard/user';
import { useMyContext } from '../provider';
import GenerateToastConfig from '../../components/toast-config/GenerateToastConfig';
import useResponsive from '../../hooks/useResponsive';
import DeleteModal from '../../components/deleteModal/DeleteModal';
import TanstackTable from '../../components/tanstackMUItable/TanstackTable';
import TanstackTableV8 from '../../components/tanstackMUItable/tanstackTableV8';

export default function Language() {
  const location = useLocation();
  const queryParams = new URLSearchParams(location.search)

  const [search, setsearch] = useState('');
  const [open, setOpen] = useState(false);
  const [page, setPage] = useState(parseInt(queryParams.get('page'), 10) || 1);
  const [deleteOpens, setDeleteOpens] = useState();
  const [order, setOrder] = useState('asc');
  const [selected, setSelected] = useState([]);
  const [orderBy, setOrderBy] = useState('name');
  const [filterName, setFilterName] = useState('');
  const [rowsPerPage, setRowsPerPage] = useState(parseInt(queryParams.get('limit'), 10) || 10);
  const [languageList, setLanguageList] = React.useState([]);
  const [totalCount, setTotalCount] = useState(0);
  const [id, setId] = useState('');
  const [lang, setLang] = useState('');
  const [isGroup, setIsGroup] = useState(false);
  const [addTranscribeDialogOpen, setAddTranscribeDialogOpen] = useState(false);
  const [addGroupDialogOpen, setAddGroupDialogOpen] = useState(false);
  const [describe, setDescribe] = useState('');
  const [selectLanguage, setSelectLanguage] = useState([]);
  const [interpret, setInterpret] = useState('');
  const [data, setData] = useState([]);
  const [selectedOption, setSelectedOption] = useState('');
  const [selectedGroup, setSelectedGroup] = useState('');
  const [groupInterpret, setGroupInterpret] = useState([]);
  const [isSubmitting, setSubmitting] = useState(false);
  const [groupSubmit, setGroupSubmit] = useState(false);
  const [transcribeEdit, setTranscribeEdit] = useState([]);
  const [selectedTableRow, setSelectedTableRow] = useState("");
  const [filters, setFilters] = useState({});
  const [isLoading, setIsLoading] = useState(true);

  const { i18 } = useMyContext();
  const isMobile = useResponsive('down', 'sm')

  const [anchorEl, setAnchorEl] = useState(null);

  const style1 = {
    position: 'absolute',
    top: '50%',
    left: '50%',
    transform: 'translate(-50%, -50%)',
    width: isMobile ? "90%" : 500,
    backgroundColor: 'white',
    borderRadius: '8px',
    boxShadow: '0px 4px 16px rgba(0, 0, 0, 0.2)',
    p: isMobile ? 2 : 4,
    height: '600px',
    overflow: "hidden",
    overflowY: "scroll",
  };

  const handleMenuOpen = (event) => {
    setAnchorEl(event.currentTarget);
  };

  const handleMenuClose = () => {
    setAnchorEl(null);
  };

  const TABLE_HEAD = [
    { id: 'interpret', label: i18?.SETTINGSLIST?.KEY || "Key", alignRight: false },
    { id: 'group', label: i18?.SETTINGSLIST?.GROUP || "Group", alignRight: false },
    { id: 'action', label: i18?.SETTINGSLIST?.ACTION || "Action", alignRight: false },
  ];


  const handleOnChange = (e) => {

    const index = parseInt(e.target.dataset.index, 10);
    setTranscribeEdit(prevItems => {
      // Create a new array with the updated item
      const updatedItems = [...prevItems];
      const currentItem = updatedItems[index];
      updatedItems[index] = {
        ...currentItem,
        transcribe: {
          ...currentItem.transcribe,
          describe: e.target.value
        }
      }
      return updatedItems;
    });
  }

  const fetchData = async () => {
    setIsLoading(true);
    try {
      let url = `module/translation/translate?page=${page}&limit=${rowsPerPage}`;
      // if (search) {
      //   url += `&search=${search}`;
      // }
      if (search) url += `&search=${search}`;
      Object.entries(filters).forEach(([key, value]) => {
        if (value) url += `&${key}=${value}`;
      });
      const res = await axios.get(url);
      if (res.status === 200) {
        setLanguageList(res.data.data.translations);
        setTotalCount(res.data.data.count);
      } else {
        GenerateToastConfig(res.data.message);
      }
    } catch (err) {
      GenerateToastConfig(err.response?.data?.message);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    GetTranslationGroup();
    SelectLanguage();
  }, [])

  useEffect(() => {
    fetchData();
  }, [page, rowsPerPage, order, orderBy, search, filters]);

  useEffect(() => {
    updateUrlParams({ page, limit: rowsPerPage });
  }, [page, rowsPerPage, search]);

  const handleformdata = async (id, lang, row) => {
    setSelectedTableRow(row)
    const res = await axios.get(`module/translation/transcribe/${id}`)

      .then((res) => {
        setTranscribeEdit(res?.data?.data)
      })
      .catch((error) => {
        console.error("Error occured", error);
      });


    setId(id);
    setLang(lang);
    setOpen(true);
  };

  const GetTranslationGroup = async () => {
    try {
      const res = await axios.get('/module/translation/translate');
      if (res.status === 200) {
        fetchData();
        const translations = res.data.data.translations || [];
        if (Array.isArray(translations)) {
          setData(translations);
        }
      }
    } catch (err) {
      console.error('Error fetching data:', err);
    }
  };

  const SelectLanguage = async () => {
    try {
      const res = await axios.get('/module/translation/languages');
      if (res.status === 200) {
        fetchData();
        setSelectLanguage(res?.data?.data?.language);
      }
    } catch (err) {
      console.error('Error fetching data:', err);
    }
  };
  const UpdateGroup = async () => {
    const newObj = await {
      translationId: selectedTableRow?._id,
      interpret: selectedTableRow?.interpret,
      group: selectedTableRow?.group?._id,
      isGroup: !selectedTableRow?.group?._id,
      transcribe: transcribeEdit?.map((each) => (
        {
          language: each?._id,
          describe: each?.transcribe?.describe
        }
      ))
    }


    try {
      const res = await axios.post(`/module/translation/transcribe`, newObj);
      if (res.status === 200) {
        GenerateToastConfig(res.data.message, 'success');
        setOpen(false);
        fetchData();
      }
    } catch (err) {
      if (err.response && err.response.data && err?.response?.data?.message) {
        GenerateToastConfig(err?.response?.data?.message);
      } else {
        GenerateToastConfig("An error occurred while updating the Group.");
      }
    };
  };

  const deleteModal = (ids) => {
    sessionStorage.setItem("useId", ids)
    setDeleteOpens(true);
  }

  const deleteIcon = async () => {
    const ids = sessionStorage.getItem("userId")
    try {
      const res = await axios.delete(`/module/translation/transcribe/${ids}`);
      if (res.status === 200) {
        setDeleteOpens(false)
        GenerateToastConfig(res.data.message, 'info');
        fetchData();
      } else {
        GenerateToastConfig(res.data.message);
      }
    } catch (err) {
      GenerateToastConfig(err?.response?.data?.message);
    }
  };

  const handleRequestSort = (event, property) => {
    const isAsc = orderBy === property && order === 'asc';
    setOrder(isAsc ? 'desc' : 'asc');
    setOrderBy(property);
  };

  const handleSelectAllClick = (event) => {
    if (event.target.checked) {
      const newSelecteds = languageList.map((n) => n.name);
      setSelected(newSelecteds);
      return;
    }
    setSelected([]);
  };

  const handleChangePage = (event, newPage) => {
    setPage(newPage + 1);
  };

  const handleChangeRowsPerPage = (event) => {
    setPage(1);
    setRowsPerPage(parseInt(event.target.value, 10));
  };

  const handleFilterByName = (event) => {
    setPage(0);
    setFilterName(event.target.value);
  };

  const handleGroupInterpretChange = (event) => {
    setGroupInterpret(event.target.value);
  };

  const handleInterpretChange = (event) => {
    setInterpret(event.target.value);
  };

  const handleDescribeChange = (event) => {
    setDescribe(event.target.value);
  };

  const handleSelectLanguageChange = (event) => {
    setSelectedOption(event.target.value);
  }

  const handleClick = () => {
    setIsGroup(!isGroup);
  }

  const LangId = selectLanguage[0]?._id;
  const GroupId = data[0]?.group?._id;

  function handleSubmit(event) {
    setSubmitting(true);
    event.preventDefault();

    const body = {
      translationId: null,
      interpret,
      group: GroupId,
      isGroup,
      transcribe: [{
        language: LangId,
        describe,
      }]
    };

    axios.post(`/module/translation/transcribe/`, body)
      .then((response) => {
        setSubmitting(false)
        setOpen(false);
        fetchData();
      })
      .catch((error) => {
        setSubmitting(false)
        console.error("Error : ", error);
      });
  }

  function handleAddGroup(event) {
    event.preventDefault();
    setGroupSubmit(true);
    const body = {
      translationId: null,
      interpret: groupInterpret,
      isGroup: true,
      transcribe: []
    }

    axios.post(`/module/translation/transcribe/`, body)
      .then((response) => {
        setGroupSubmit(false);
        setOpen(false);
        fetchData();
      })
      .catch((error) => {
        setGroupSubmit(false);
        console.error("Error occured", error);
      });
  }

  const handleGenerateJson = async () => {
    const res = await axios.post(`/module/translation/transcribe/generate`);
    if (res?.status === 200) {
      GenerateToastConfig(res.data, 'info');
    } else {
      GenerateToastConfig(res.data);
    }
  }

  const ActionComponent = (cell) => {
    const value = cell?.getValue();
    const original = cell?.row?.original;
    const [anchorEl, setAnchorEl] = useState(null);
    const [menuRowId, setMenuRowId] = useState(null);

    const handleActionMenu = (event, rowId) => {
      setAnchorEl(event.currentTarget);
      setMenuRowId(rowId);
    };

    const handleActionMenuClose = () => {
      setAnchorEl(null);
      setMenuRowId(null);
    };

    return (
      <>
        <IconButton
          sx={{
            width: '37px',
            height: '37px',
            background: '#EBEBEB',
            color: 'black',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            borderRadius: '50%',
          }}
          onClick={(event) => handleActionMenu(event, value)}
        >
          <Iconify icon="mdi:dots-horizontal" />
        </IconButton>
        <Popover
          anchorEl={anchorEl}
          open={Boolean(anchorEl) && menuRowId === value}
          onClose={handleActionMenuClose}
          anchorOrigin={{ vertical: 'top', horizontal: 'left' }}
          transformOrigin={{ vertical: 'top', horizontal: 'right' }}
          PaperProps={{
            sx: { width: 140 },
          }}
        >
          <MenuItem onClick={() => handleformdata(value, original?.Language, original)}>
            <Iconify icon={'carbon:edit'} sx={{ mr: 2 }} /> Edit
          </MenuItem>
          <MenuItem onClick={() => deleteModal(value)} sx={{ color: 'error.main' }}>
            <Iconify icon={'eva:trash-2-outline'} sx={{ mr: 2 }} /> Delete
          </MenuItem>
        </Popover>
      </>
    );
  }

  const columns = [
    {
      header: i18?.SETTINGSLIST?.KEY || "Key",
      id: "interpret",
      accessorKey: "interpret",
      showFilter: true,
      cell: ({ row }) => <span>{row?.original?.interpret || '---'}</span>,
    },
    {
      header: i18?.SETTINGSLIST?.GROUP || "Group",
      id: "group",
      accessorKey: "group",
      showFilter: false,
      cell: ({ row }) => <span>{row?.original?.group?.interpret || '---'}</span>,
    },
    {
      header: i18?.SETTINGSLIST?.ACTION || "Action",
      id: "action",
      accessorKey: "_id",
      cell: ActionComponent,
    },
  ]

  // const columns = useMemo(() => COLUMNS, []);
  // const tdata = React.useMemo(() => languageList.map((user) => {
  //   return {
  //     interpret: user?.interpret,
  //     group: user?.group?.interpret,
  //     action: user?._id,
  //     data: user,
  //   };
  // }), [languageList]);

  const handleFilterChange = (filterKey, value) => {
    setFilters((prev) => ({ ...prev, [filterKey]: value }));
    setPage(1);
  };

  return (
    <>
      <Helmet>
        <title> Translations | Admin panel </title>
      </Helmet>

      {isMobile && <Typography sx={{ marginBottom: '30px' }} variant="h4" gutterBottom>
        {i18?.SETTINGSLIST?.LIST_TRANSCRIBE || "List Transcribe"}
      </Typography>}

      {!isMobile && <Stack direction="row" alignItems="center" justifyContent="space-between" mb={0}>
        <Typography variant="h4" gutterBottom>
          {i18?.SETTINGSLIST?.LIST_TRANSCRIBE || "List Transcribe"}
        </Typography>
        <Stack direction="row" alignItems="center">

          <UserListToolbar
            numSelected={selected.length}
            filterName={filterName}
            onFilterName={handleFilterByName}
            search={search}
            setsearch={(value) => {
              setsearch(value);
              setPage(1);
            }}
          />
          <Button variant="contained" onClick={() => setAddTranscribeDialogOpen(true)} startIcon={<Iconify icon="eva:plus-fill" />} style={{ marginLeft: "5px" }}>
            {i18?.SETTINGSLIST?.ADD_TRANSCRIBE || "Add Transcribe"}
          </Button>
          <Button variant="contained" onClick={() => handleGenerateJson()} startIcon={<Iconify icon="eva:plus-fill-a" />} style={{ marginLeft: "5px" }}>
            {i18?.SETTINGSLIST?.GENERATE_JSON || "Generate JSON"}
          </Button>
        </Stack>
      </Stack>}


      <Card>
        {isMobile && (
          <>
            <Stack direction="row" alignItems="center" justifyContent="space-between" sx={{ paddingRight: '0px' }}>
              <UserListToolbar
                numSelected={selected.length}
                filterName={filterName}
                onFilterName={handleFilterByName}
                search={search}
                setsearch={(value) => {
                  setsearch(value);
                  setPage(1);
                }}
              />
              <Stack direction="row" justifyContent="flex-end">
                <IconButton onClick={handleMenuOpen}>
                  <MoreVertIcon />
                </IconButton>
                <Menu
                  anchorEl={anchorEl}
                  open={Boolean(anchorEl)}
                  onClose={handleMenuClose}
                >
                  <MenuItem onClick={() => { setAddTranscribeDialogOpen(true); handleMenuClose(); }}>
                    {i18?.SETTINGSLIST?.ADD_TRANSCRIBE || "Add Transcribe"}
                  </MenuItem>
                  <MenuItem onClick={() => { handleGenerateJson(); handleMenuClose(); }}>
                    {i18?.SETTINGSLIST?.GENERATE_JSON || "Generate JSON"}
                  </MenuItem>
                </Menu>
              </Stack>
            </Stack>
          </>
        )}

        <Scrollbar>
          {/* <TanstackTable data={tdata} columns={columns} /> */}
          <TanstackTableV8
            data={languageList}
            columns={columns}
            filters={filters}
            isLoading={isLoading}
            onFilterChange={handleFilterChange}
          />
        </Scrollbar>

      </Card>
      <TablePagination
        rowsPerPageOptions={[5, 10, 25]}
        component="div"
        count={totalCount || '0'}
        rowsPerPage={rowsPerPage}
        page={page - 1}
        onPageChange={handleChangePage}
        onRowsPerPageChange={handleChangeRowsPerPage}
        sx={{
          '.MuiTablePagination-selectLabel': {
            marginTop: '12px',
          },
          '.MuiTablePagination-displayedRows': {
            marginTop: '12px',
          },
          '.MuiTablePagination-actions': {
            marginBottom: '6px',
          }
        }}
      />
      <Modal open={addTranscribeDialogOpen} onClose={() => setAddTranscribeDialogOpen(false)}>
        <form onSubmit={handleSubmit}>
          <Box sx={{
            position: 'absolute',
            top: '50%',
            left: '50%',
            transform: 'translate(-50%, -50%)',
            width: isMobile ? "90%" : 400,
            backgroundColor: 'white',
            borderRadius: '8px',
            boxShadow: '0px 4px 16px rgba(0, 0, 0, 0.2)',
            p: isMobile ? 2 : 4,
          }}>
            <Typography id="modal-modal-title" variant="h6" component="h2">
              {i18?.SETTINGSLIST?.ADD_TRANSCRIBE || "Add Transcribe"}
            </Typography>
            <div className="mb-2 mt-2">
              <TextField
                id="Interpret"
                label={i18?.SETTINGSLIST?.INTERPRET || "Interpret"}
                variant="outlined"
                value={interpret}
                onChange={(e) => {
                  const inputValue = e.target.value;
                  const onlyAlphabeticChars = inputValue.replace(/[^a-zA-Z]/g, '');
                  setInterpret(onlyAlphabeticChars.toUpperCase());
                  handleInterpretChange(e);
                }}
                fullWidth
              />
            </div>

            <div style={{ display: 'flex', alignItems: 'center', marginBottom: '10px' }}>
              <FormControl sx={{ display: '', justifyContent: 'flex-end', minWidth: 160 }} size="small">
                <InputLabel id="demo-select-small-label">{i18?.SETTINGSLIST?.SELECT_GROUP || "Select Group"}</InputLabel>
                <Select
                  labelId="demo-select-small-label"
                  id="demo-select-small"
                  value={selectedGroup}
                  label="translationList"
                  onChange={(e) => setSelectedGroup(e.target.value)}
                >
                  {Array.isArray(languageList) && languageList.map((translation, index) => (
                    <MenuItem key={index} value={translation?.group && translation?.group?.interpret}>
                      {translation?.group?.interpret}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
              <div style={{ display: 'flex', alignItems: 'center', marginLeft: '30px' }}>{i18?.SETTINGSLIST?.STATUS || "Status"}
                <Switch
                  checked={isGroup}
                  onChange={handleClick}
                  inputProps={{ 'aria-label': 'controlled' }}
                />
              </div>
            </div>

            <div className="mb-2 mt-2">
              <FormControl sx={{ minWidth: 165 }} size="small">
                <InputLabel id="demo-select-small-label">{i18?.SETTINGSLIST?.SELECT_LANGUAGE || "Select Language"}</InputLabel>
                <Select
                  labelId="demo-select-small-label"
                  id="demo-select-small"
                  value={selectedOption}
                  label="SelectLanguage"
                  onChange={handleSelectLanguageChange}
                >
                  {selectLanguage && Array.isArray(selectLanguage) && selectLanguage.map((language, index) => (
                    <MenuItem key={index} value={language.name}>
                      {language.name}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </div>

            <div className="mb-2 mt-2">
              <TextField
                id="describe"
                label={i18?.SETTINGSLIST?.DESCRIBE || "Describe"}
                variant="outlined"
                value={describe}
                onChange={handleDescribeChange}
                fullWidth
              />
            </div>
            <div style={{ display: 'flex', justifyContent: 'end' }}>
              <Button variant="contained" type="submit" disabled={isSubmitting}>{i18?.SETTINGSLIST?.ADD || "Add"}</Button>
            </div>
          </Box>
        </form>
      </Modal>


      <Modal open={addGroupDialogOpen} onClose={() => setAddGroupDialogOpen(false)}>
        <form onSubmit={handleAddGroup}>
          <Box sx={{
            position: 'absolute',
            top: '50%',
            left: '50%',
            transform: 'translate(-50%, -50%)',
            width: isMobile ? "90%" : 400,
            backgroundColor: 'white',
            borderRadius: '8px',
            boxShadow: '0px 4px 16px rgba(0, 0, 0, 0.2)',
            p: isMobile ? 2 : 4,
          }}>
            <Typography id="modal-modal-title" variant="h6" component="h2">
              {i18?.SETTINGSLIST?.ADD_GROUP || "Add Group"}
            </Typography>
            <div className="mb-2 mt-2">
              <TextField
                id="Interpret"
                label="Interpret"
                variant="outlined"
                value={groupInterpret}
                onChange={(e) => {
                  const inputValue = e.target.value;
                  const onlyAlphabeticChars = inputValue.replace(/[^a-zA-Z]/g, '');
                  setGroupInterpret(onlyAlphabeticChars.toUpperCase());
                  handleGroupInterpretChange(e);
                }}
                fullWidth
              />
            </div>

            <div style={{ display: 'flex', justifyContent: 'end' }}>
              <Button variant="contained" type="submit" disabled={groupSubmit}>
                {i18?.SETTINGSLIST?.ADD || "Add"}
              </Button>
            </div>
          </Box>
        </form>
      </Modal>



      <Modal
        open={open}
        onClose={() => setOpen(false)}
        aria-labelledby="modal-modal-title"
        aria-describedby="modal-modal-description"
      >
        <Box sx={style1}>
          <Typography id="modal-modal-title" variant="h6" component="h2" sx={{ marginBottom: "20px" }}>
            {i18?.SETTINGSLIST?.UPDATE_GROUP || "Update Group"}
          </Typography>
          {transcribeEdit?.map((each, index) => (
            <div key={index}>
              <p style={{ color: "#187699" }}>{each?.name}</p>
              <div>
                <TextField
                  name={each?.name}
                  inputProps={{
                    "data-index": index
                  }}
                  id="outlined-basic"
                  label={i18?.SETTINGSLIST?.INTERPRET || "Interpret"}
                  variant="outlined"
                  value={each?.transcribe?.describe}
                  onChange={handleOnChange}
                  sx={{
                    margin: '10px 0px',
                    width: '100%',
                    '& .MuiOutlinedInput-root': {
                      '& fieldset': {
                        borderColor: 'black',
                      },
                    },
                  }}
                />
              </div>
            </div>
          ))}
          <div style={{ display: 'flex', justifyContent: 'space-between	' }}>
            <Button variant="contained" size="medium" color="primary" onClick={() => setOpen(false)}>
              {' '}
              {i18?.SETTINGSLIST?.CLOSE || "Close"}
            </Button>
            <Button variant="contained" size="medium" color="primary" onClick={UpdateGroup}>
              {' '}
              {i18?.SETTINGSLIST?.UPDATE || "Update"}
            </Button>
          </div>
        </Box>
      </Modal>

      <DeleteModal
        isDeleteOpen={deleteOpens}
        handleClose={() => setDeleteOpens(false)}
        handleDelete={deleteIcon}
      />

    </>
  );
}